insert into community_festivals values ('lhosar', 'sonam-lhosar', 'सोनाम ल्होसार', 'Sonam Lhosar', 'Tamang & Hyolmo New Year', '{"kind":"lunar","system":"amanta","month":10,"paksha":"shukla","tithi":1,"observance":"udaya"}'::jsonb, 0, 1, null, array['तामाङ','ह्योल्मो']::text[], 'माघ शुक्ल प्रतिपदा (जाडो अयनान्तपछिको दोस्रो औंसीपछि) मनाइने तामाङ र ह्योल्मोको नयाँ वर्ष।', array['गुम्बा र स्तुपा दर्शन, मुकुण्डो नाच','घर सफा गरी देवताको स्वागत','तामाङ सेलो र डम्फु, ह्योल्मो/रसुवामा स्याब्रु नाच','ह्योल्मो परिकार: खाप्से, बबर, थोङसे']::text[], array['बौद्ध','स्वयम्भू','बागमती प्रदेशका तामाङ बस्ती']::text[], 'national', true, 'sourced', array['https://radionepalonline.com/en/2026/01/19/423441.html','https://en.wikipedia.org/wiki/Sonam_Lhosar']::text[]) on conflict (suite, id) do update set rule = excluded.rule, summary = excluded.summary;
insert into community_festivals values ('lhosar', 'tamu-lhosar', 'तमु ल्होसार', 'Tamu Lhosar', 'Gurung New Year', '{"kind":"bs","month":9,"day":15}'::jsonb, 0, 1, null, array['गुरुङ']::text[], 'पुस १५ मा मनाइने गुरुङ (तमु) समुदायको नयाँ वर्ष; पुरानो ल्होलाई बिदाइ गरी नयाँ ल्हो स्वागत।', array['स्वयम्भू र बौद्धमा लुङ्दर (प्रार्थना झण्डा)','परम्परागत पहिरन','घाटु र चुड्का नाच','पुस १५ मा जन्मेको बच्चा नयाँ ल्हो, पुस १४ मा जन्मेको पुरानो ल्होमा पर्छ']::text[], array['टुँडिखेल/काठमाडौं','पोखरा','लमजुङ','गोरखा','कास्की']::text[], 'national', false, 'sourced', array['https://en.wikipedia.org/wiki/Tamu_Lhosar','https://www.tamupariwarny.org/gurung-lho-system','https://github.com/kitsuyui/hyper-calendar/pull/97']::text[]) on conflict (suite, id) do update set rule = excluded.rule, summary = excluded.summary;
insert into community_festivals values ('lhosar', 'gyalpo-lhosar', 'ग्याल्पो ल्होसार', 'Gyalpo Lhosar', 'Sherpa & Tibetan New Year', '{"kind":"tibetan-new-year"}'::jsonb, 0, 1, null, array['शेर्पा','तामाङ','भोटिया','तिब्बती']::text[], 'तिब्बती पात्रोको पहिलो दिन (फेब्रुअरी ३ पछिको पहिलो औंसीपछिको दिन) मनाइने शेर्पा र भोटे समुदायको नयाँ वर्ष।', array['छ्याङकोल, गुथुक सुप, खाप्से','गुम्बामा चाम (मुकुण्डो नाच) र मन्त्र','मशाल र पटाकाले नराम्रो शक्ति धपाउने']::text[], array['बौद्ध','खुम्बु','पोखरा','सोलुखुम्बु']::text[], 'national', true, 'sourced', array['https://en.wikipedia.org/wiki/Gyalpo_Losar','https://www.sherpakyidug.org/annual-sherpa-gyalpo-losar-party-2026-year-of-the-fire-male-horse-2153-celebration/','https://github.com/kitsuyui/hyper-calendar/pull/97']::text[]) on conflict (suite, id) do update set rule = excluded.rule, summary = excluded.summary;
