insert into community_festivals values ('tharu', 'maghi', 'माघी', 'Maghi', 'Tharu New Year', '{"kind":"sankranti","rashi":9}'::jsonb, 3, 5, null, array['थारू']::text[], 'थारू समुदायको नयाँ वर्ष र सबैभन्दा ठूलो पर्व। क्षेत्रअनुसार १–३ दिनदेखि पुस २८ – माघ २ सम्म।', array['पुस २८: माछा मार्ने; पुस २९: (केही ठाउँमा) बँदेल सिकार','बिहानै स्नान र टीका; दाजुभाइले दिदीबहिनीलाई चामल, दाल, नुन (निस्राउ) दिने','आगो वरिपरि ढोल–नाच, मघौटा/सखिया नाच','अवधि जिल्लाअनुसार १–३ दिन फरक (बर्दिया, कपिलवस्तु, रुपन्देही, दाङ) — स्थानीय विवरण समुदायबाट लिनुहोस्','बरघर/बडघर, चौकीदार, लोहार, गुरुवा छान्ने/नवीकरण गर्ने गाउँ भेला — सामाजिक नियम पनि बनाइन्छ','परिकार: जाँड, ढिकरी, खिचडी, घोंघी, तिलको लड्डु, भुजा, माछा']::text[], array['बर्दिया','दाङ','कैलाली','कञ्चनपुर','बाँके','कपिलवस्तु','रुपन्देही','चितवन']::text[], 'national', false, 'sourced', array['https://kathmandupost.com/art-culture/2024/01/15/delicacies-and-rituals-of-maghi','https://risingnepaldaily.com/news/55284','https://ekantipur.com/news/2025/01/15/en/maghi-festival-in-tharu-settlement-15-10.html']::text[]) on conflict (suite, id) do update set rule = excluded.rule, summary = excluded.summary;
