insert into community_festivals values ('kirat', 'yele-new-year', 'येले सम्वत् नयाँ वर्ष (काक्फेक्वा तङनाम)', 'Yele Sambat New Year', 'Kirat New Year', '{"kind":"sankranti","rashi":9}'::jsonb, 0, 1, null, array['राई','लिम्बू','याक्खा','सुनुवार']::text[], 'किरात येले सम्वत्को नयाँ वर्ष; तरुल, सखरखण्ड र सेलरोटी खाने चलन।', array[]::text[], array[]::text[], 'national', false, 'review', array['https://en.wikipedia.org/wiki/Yele_Sambat','https://mundhum.com/calendar']::text[]) on conflict (suite, id) do update set rule = excluded.rule, summary = excluded.summary;
insert into community_festivals values ('hijri', 'islamic-new-year', 'हिजरी नयाँ वर्ष', 'Islamic New Year', '1 Muharram', '{"kind":"hijri","month":1,"day":1}'::jsonb, 0, 1, null, array['मुस्लिम']::text[], 'हिजरी सम्वत्को पहिलो दिन।', array[]::text[], array[]::text[], 'none', false, 'derived', array[]::text[]) on conflict (suite, id) do update set rule = excluded.rule, summary = excluded.summary;
insert into community_festivals values ('hijri', 'ashura', 'आशुरा', 'Ashura', '10 Muharram', '{"kind":"hijri","month":1,"day":10}'::jsonb, 0, 1, null, array['मुस्लिम']::text[], 'मुहर्रमको दशौं दिन; ताजिया जुलुस (कतिपय स्थानमा)।', array[]::text[], array[]::text[], 'none', false, 'derived', array[]::text[]) on conflict (suite, id) do update set rule = excluded.rule, summary = excluded.summary;
insert into community_festivals values ('hijri', 'mawlid', 'मिलाद–उन–नबी', 'Mawlid an-Nabi', '12 Rabi al-Awwal', '{"kind":"hijri","month":3,"day":12}'::jsonb, 0, 1, null, array['मुस्लिम']::text[], 'पैगम्बर मुहम्मदको जन्मदिन मनाउने दिन (परम्पराअनुसार)।', array[]::text[], array[]::text[], 'none', false, 'derived', array[]::text[]) on conflict (suite, id) do update set rule = excluded.rule, summary = excluded.summary;
insert into community_festivals values ('hijri', 'shab-e-miraj', 'शब–ए–मेराज', 'Shab-e-Miraj', 'Night of 27 Rajab', '{"kind":"hijri","month":7,"day":27,"eve":true}'::jsonb, 0, 1, null, array['मुस्लिम']::text[], 'रजब २७ को रात।', array[]::text[], array[]::text[], 'none', false, 'derived', array[]::text[]) on conflict (suite, id) do update set rule = excluded.rule, summary = excluded.summary;
insert into community_festivals values ('hijri', 'shab-e-barat', 'शब–ए–बरात', 'Shab-e-Barat', 'Night of 15 Sha’ban', '{"kind":"hijri","month":8,"day":15,"eve":true}'::jsonb, 0, 1, null, array['मुस्लिम']::text[], 'शाबान १४–१५ को रात; प्रार्थना र पितृ सम्झना।', array[]::text[], array[]::text[], 'none', false, 'derived', array[]::text[]) on conflict (suite, id) do update set rule = excluded.rule, summary = excluded.summary;
insert into community_festivals values ('hijri', 'ramadan-start', 'रमजान सुरु', 'Ramadan begins', '1 Ramadan', '{"kind":"hijri","month":9,"day":1}'::jsonb, 0, 29, null, array['मुस्लिम']::text[], 'रोजाको महिना; सेहरी र इफ्तारको समय तल हेर्नुहोस्।', array[]::text[], array[]::text[], 'none', true, 'derived', array[]::text[]) on conflict (suite, id) do update set rule = excluded.rule, summary = excluded.summary;
insert into community_festivals values ('hijri', 'laylat-al-qadr', 'शब–ए–कद्र', 'Laylat al-Qadr', 'Night of 27 Ramadan', '{"kind":"hijri","month":9,"day":27,"eve":true}'::jsonb, 0, 1, null, array['मुस्लिम']::text[], 'रमजानको अन्तिम दश रातमध्ये (प्रायः २७ औं रात)।', array[]::text[], array[]::text[], 'none', false, 'derived', array[]::text[]) on conflict (suite, id) do update set rule = excluded.rule, summary = excluded.summary;
insert into community_festivals values ('hijri', 'eid-ul-fitr', 'ईद–उल–फित्र', 'Eid ul-Fitr', '1 Shawwal', '{"kind":"hijri","month":10,"day":1}'::jsonb, 0, 1, null, array['मुस्लिम']::text[], 'रमजानपछिको ईद। नेपालमा मुस्लिम आयोगको चन्द्रदर्शनको आधारमा गृह मन्त्रालयले बिदा घोषणा गर्छ।', array[]::text[], array[]::text[], 'national', true, 'sourced', array['https://english.ratopati.com/story/54693/eid-ul-fitr-on-saturday-ministry-of-home-affairs-issues-notice','https://kathmandupost.com/national/2025/03/30/government-declares-public-holiday-on-monday']::text[]) on conflict (suite, id) do update set rule = excluded.rule, summary = excluded.summary;
insert into community_festivals values ('hijri', 'eid-al-adha', 'ईद–उल–अजहा (बकर ईद)', 'Eid al-Adha', '10 Dhu al-Hijjah', '{"kind":"hijri","month":12,"day":10}'::jsonb, 0, 1, null, array['मुस्लिम']::text[], 'कुर्बानीको ईद; हज्जको समयसँग जोडिएको।', array[]::text[], array[]::text[], 'national', true, 'sourced', array['https://english.nepalnews.com/s/nation/public-holiday-announced-on-may-28-for-eid-al-adha/']::text[]) on conflict (suite, id) do update set rule = excluded.rule, summary = excluded.summary;
